      cursor: pointer;
      color: white;
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      box-shadow: 0 14px 30px rgba(185, 28, 28, 0.35);
      transition: transform 160ms ease, filter 160ms ease;
